<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Str;
class AuthController extends Controller { public function loginForm(){return view('auth.login');} public function login(Request $request){$credentials=$request->validate(['email'=>'required|email','password'=>'required|string']);$credentials['email']=Str::lower(trim($credentials['email']));if(Auth::attempt(array_merge($credentials,['active'=>true]),$request->boolean('remember'))){$request->session()->regenerate();app()->setLocale($request->user()->locale);return redirect()->intended(route('dashboard'));}return back()->withErrors(['email'=>__('ui.invalid_credentials')])->onlyInput('email');} public function logout(Request $request){Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('login');} public function locale(Request $request,string $locale){abort_unless(in_array($locale,['fa','en']),404);if($request->user())$request->user()->update(['locale'=>$locale]);session(['locale'=>$locale]);return back();} }
